#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const int INF = 1e9;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, k;
    long long t;
    if (!(cin >> n >> k >> t)) return 0;

    vector<int> p(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> p[i];
    }

    vector<int> pos(k + 1);
    int current_k = 0;
    for (int i = 1; i <= n; ++i) {
        int g;
        cin >> g;
        if (g == 1) {
            current_k++;
            pos[current_k] = i;
        }
    }

    int max_v = 9 * k;
    vector<vector<int>> dp(k + 1, vector<int>(max_v + 1, INF));
    dp[0][0] = 0;

    for (int i = 1; i <= n; ++i) {
        int limit_j = min(i, k);
        for (int j = limit_j; j >= 1; --j) {
            int cost_move = abs(pos[j] - i);
            int max_val_j = 9 * j;
            int pi = p[i];
            for (int v = max_val_j; v >= pi; --v) {
                if (dp[j - 1][v - pi] != INF) {
                    dp[j][v] = min(dp[j][v], dp[j - 1][v - pi] + cost_move);
                }
            }
        }
    }

    int ans = 0;
    for (int v = max_v; v >= 0; --v) {
        if (dp[k][v] <= t) {
            ans = v;
            break;
        }
    }

    cout << ans << "\n";

    return 0;
}
